import Button from '@tecton-mui/ui/Button';
import Dialog from '@tecton-mui/ui/Dialog';
import DialogActions from '@tecton-mui/ui/DialogActions';
import DialogContent from '@tecton-mui/ui/DialogContent';
import DialogContentText from '@tecton-mui/ui/DialogContentText';
import DialogTitle from '@tecton-mui/ui/DialogTitle';
import useMediaQuery from '@tecton-mui/ui/useMediaQuery';
import { useTheme } from '@tecton-mui/ui/styles';

export default function ResponsiveDialog() {
  const [open, setOpen] = React.useState(false);
  const theme = useTheme();
  const fullScreen = useMediaQuery(theme.breakpoints.down('md'));

  const handleClickOpen = () => {
    setOpen(true);
  };

  const handleClose = () => {
    setOpen(false);
  };

  return (
    <React.Fragment>
      <Button variant="outlined" onClick={handleClickOpen}>
        Open responsive dialog
      </Button>
      <Dialog
        fullScreen={fullScreen}
        open={open}
        onClose={handleClose}
        aria-labelledby="responsive-dialog-title"
      >
        <DialogTitle id="responsive-dialog-title">
          {"Use Google's location service?"}
        </DialogTitle>
        <DialogContent>
          <DialogContentText>
            Let Google help apps determine location. This means sending anonymous
            location data to Google, even when no apps are running.
          </DialogContentText>
        </DialogContent>
        <DialogActions>
          <Button autoFocus onClick={handleClose}>
            Disagree
          </Button>
          <Button onClick={handleClose} autoFocus>
            Agree
          </Button>
        </DialogActions>
      </Dialog>
    </React.Fragment>
  );
}
